CREATE DATABASE IF NOT EXISTS care_reminders CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE care_reminders;

-- The Flask models create these tables automatically. This file documents the normalized MySQL shape.
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, phone VARCHAR(30), password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_settings (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL UNIQUE, water_target_ml INT NOT NULL DEFAULT 2000, water_reminder_times VARCHAR(255), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE patient_profiles (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL UNIQUE, age INT, gender VARCHAR(40), emergency_contact VARCHAR(120), caregiver_info TEXT, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE medicines (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, name VARCHAR(120) NOT NULL, dosage VARCHAR(120) NOT NULL, quantity DECIMAL(10,2) DEFAULT 0, low_stock_threshold DECIMAL(10,2) DEFAULT 0, start_date DATE, end_date DATE, instructions VARCHAR(255), notes TEXT, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE medicine_schedules (id INT AUTO_INCREMENT PRIMARY KEY, medicine_id INT NOT NULL, time TIME NOT NULL, start_date DATE NOT NULL, end_date DATE, frequency VARCHAR(30) NOT NULL, FOREIGN KEY (medicine_id) REFERENCES medicines(id) ON DELETE CASCADE);
CREATE TABLE medicine_logs (id INT AUTO_INCREMENT PRIMARY KEY, schedule_id INT NOT NULL, user_id INT NOT NULL, event_date DATE NOT NULL, status VARCHAR(20) NOT NULL, snoozed_until DATETIME, FOREIGN KEY (schedule_id) REFERENCES medicine_schedules(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE water_logs (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, amount_ml INT NOT NULL, logged_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE daily_activities (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, name VARCHAR(120) NOT NULL, time TIME, activity_date DATE NOT NULL, frequency VARCHAR(30) DEFAULT 'Once', FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE activity_logs (id INT AUTO_INCREMENT PRIMARY KEY, activity_id INT NOT NULL, status VARCHAR(20) NOT NULL, logged_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (activity_id) REFERENCES daily_activities(id) ON DELETE CASCADE);
CREATE TABLE health_records (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, metric VARCHAR(40) NOT NULL, value VARCHAR(80) NOT NULL, recorded_at DATETIME DEFAULT CURRENT_TIMESTAMP, notes TEXT, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE notifications (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(160) NOT NULL, message TEXT NOT NULL, notification_key VARCHAR(180), is_read BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
